<?php $tabs=['general'=>'عمومی','branding'=>'برندینگ','security'=>'امنیت'];?>
<section class="panel form-panel"><div class="settings-tabs"><?php foreach($tabs as$key=>$label):?><a class="<?= $section===$key?'active':'' ?>" href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/settings/'.$key)) ?>"><?= $label ?></a><?php endforeach;?></div><form method="post" enctype="multipart/form-data" action="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/settings/'.$section)) ?>"><input type="hidden" name="_csrf" value="<?= \CardPay\Core\View::e($csrf) ?>"><div class="fields two"><?php if($section==='general'):?><label>واحد پول<select name="currency"><option value="IRR">ریال (IRR)</option></select></label><label>منطقه زمانی<input name="timezone" value="<?= \CardPay\Core\View::e($values['timezone']??'Asia/Tehran') ?>" dir="ltr"></label><label>تعداد رقم توکن پیش‌فرض<select name="default_token_digits"><option value="3" <?= (int)($values['default_token_digits']??3)===3?'selected':'' ?>>۳ رقم</option><option value="2" <?= (int)($values['default_token_digits']??3)===2?'selected':'' ?>>۲ رقم</option></select></label><label>اعتبار پیش‌فرض (دقیقه)<input name="default_expiration_minutes" type="number" min="1" max="10080" value="<?= (int)($values['default_expiration_minutes']??30) ?>"></label><label>Cooldown توکن (دقیقه)<input name="token_cooldown_minutes" type="number" min="1" max="1440" value="<?= (int)($values['token_cooldown_minutes']??10) ?>"></label><?php elseif($section==='branding'):?><label>نام نرم‌افزار<input name="app_name" value="<?= \CardPay\Core\View::e($values['app_name']??'CardPay') ?>"></label><label>رنگ اصلی<input name="primary_color" type="color" value="<?= \CardPay\Core\View::e($values['primary_color']??'#155EEF') ?>"></label><label>رنگ Accent<input name="accent_color" type="color" value="<?= \CardPay\Core\View::e($values['accent_color']??'#12B76A') ?>"></label><label>لوگو (PNG/JPG/WebP)<input name="logo" type="file" accept="image/png,image/jpeg,image/webp"><?php if(!empty($values['logo_path'])):?><small>فایل فعلی: <?= \CardPay\Core\View::e($values['logo_path']) ?></small><?php endif;?></label><label>Favicon (PNG/ICO)<input name="favicon" type="file" accept="image/png,image/x-icon"><?php if(!empty($values['favicon_path'])):?><small>فایل فعلی: <?= \CardPay\Core\View::e($values['favicon_path']) ?></small><?php endif;?></label><label class="full">عنوان صفحه پرداخت<input name="payment_title" value="<?= \CardPay\Core\View::e($values['payment_title']??'') ?>"></label><label class="full">متن راهنما<textarea name="payment_help" rows="3"><?= \CardPay\Core\View::e($values['payment_help']??'') ?></textarea></label><label>متن موفقیت<textarea name="success_text" rows="3"><?= \CardPay\Core\View::e($values['success_text']??'') ?></textarea></label><label>متن انقضا<textarea name="expired_text" rows="3"><?= \CardPay\Core\View::e($values['expired_text']??'') ?></textarea></label><label>اطلاعات پشتیبانی<input name="support_contact" value="<?= \CardPay\Core\View::e($values['support_contact']??'') ?>"></label><label>Footer<input name="footer" value="<?= \CardPay\Core\View::e($values['footer']??'') ?>"></label><?php else:?><label>عمر Session (دقیقه)<input name="session_lifetime" type="number" min="5" max="1440" value="<?= (int)($values['session_lifetime']??120) ?>"></label><label>حداکثر آپلود (MB)<input name="upload_max_mb" type="number" min="1" max="20" value="<?= (int)($values['upload_max_mb']??5) ?>"></label><label>نگهداری Log (روز)<input name="log_retention" type="number" min="1" max="365" value="<?= (int)($values['log_retention']??30) ?>"></label><div class="alert info full">Cookie امن، CSRF، HMAC و Rate limit همیشه فعال‌اند و از این صفحه خاموش نمی‌شوند.</div><?php endif;?></div><div class="form-actions"><button class="btn primary">ذخیره تنظیمات</button></div></form></section>
